notes:
/* SIX CELLS, ONE FIELD. One invisible input over the row;
   the cells are drawn underneath, so paste, autofill and
   backspace stay the browser's. */
<input inputmode="numeric" autocomplete="one-time-code" maxlength="6" />

/* A RIGHT CODE FUSES. The cells sit under a blur-and-threshold
   filter, too far apart for it to bridge them. Verifying slides
   them to the middle while a capsule grows out of the same
   point, and the filter joins them into one shape. */
x = mix(i * (36 + 7), centre, ease(m));          /* m: 0 -> 1 over 560ms */
.otp-goo { filter: url(#goo); }                   /* blur 3, alpha x24 */

/* A WRONG ONE SHIVERS AND DRAINS: a decaying wave down the
   row, then the digits fall out right to left. */
x += 5 * exp(-t / 190) * sin(t * 2π * 10 + i * 0.55);

/* and every digit rises into its cell out of a little blur */
@keyframes otp-in { from { transform: translateY(45%) scale(.86); opacity: 0; filter: blur(3px); } }
